'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { PACKAGES as initialPackages } from '@/data/mockData';

const PackageContext = createContext();

export const PackageProvider = ({ children }) => {
    // In a real app, this would fetch from an API
    const [packages, setPackages] = useState(initialPackages);

    // Load from localStorage if available (simulating persistence)
    useEffect(() => {
        const stored = localStorage.getItem('flight99_packages');
        if (stored) {
            setPackages(JSON.parse(stored));
        }
    }, []);

    // Save to localStorage on change
    useEffect(() => {
        localStorage.setItem('flight99_packages', JSON.stringify(packages));
    }, [packages]);

    const addPackage = (newPackage) => {
        const pkgWithId = { ...newPackage, id: Date.now() }; // Simple ID generation
        setPackages([...packages, pkgWithId]);
    };

    const updatePackage = (id, updatedData) => {
        setPackages(packages.map(pkg => pkg.id === id ? { ...pkg, ...updatedData } : pkg));
    };

    const deletePackage = (id) => {
        setPackages(packages.filter(pkg => pkg.id !== id));
    };

    return (
        <PackageContext.Provider value={{ packages, addPackage, updatePackage, deletePackage }}>
            {children}
        </PackageContext.Provider>
    );
};

export const usePackages = () => {
    const context = useContext(PackageContext);
    if (!context) {
        throw new Error('usePackages must be used within a PackageProvider');
    }
    return context;
};
